  // Applies the configured NEEV 4D design tokens (colours, fonts, spacing).
  function applyThemeTokens() {
    const sc = state.superConfig || {};
    const rootStyle = document.documentElement.style;
    const tokenMap = {
      header_bg_color: '--mm-header-bg',
      header_dark_color: '--mm-red-dark',
      sidebar_bg_color: '--mm-sidebar-bg',
      sidebar_text_color: '--mm-sidebar-text',
      primary_btn_color: '--mm-green',
      page_bg_color: '--mm-page-bg',
      card_bg_color: '--mm-card-bg',
      card_border_radius: '--mm-radius',
      navbar_height: '--mm-navbar-height',
      sidebar_width: '--mm-sidebar-width',
      font_size_base: '--mm-font-size-base',
      heading_font_weight: '--mm-heading-weight',
      loader_color: '--nmfa-loader-color',
    };
    Object.keys(tokenMap).forEach((key) => {
      if (sc[key]) rootStyle.setProperty(tokenMap[key], sc[key]);
    });
    if (sc.font_family) {
      rootStyle.setProperty('--mm-font-family', sc.font_family);
      document.body.style.fontFamily = sc.font_family;
    }
    if (sc.font_size_base) document.body.style.fontSize = sc.font_size_base;
    document.body.classList.remove('mm-live-edit-mode');
    document.body.classList.add('software-2-neev-ui');
  }

