  function showToast(msg, isError = false) {
    state.toast = { msg, isError };
    renderApp();
    setTimeout(() => {
      if (state.toast && state.toast.msg === msg) {
        state.toast = null;
        renderApp();
      }
    }, 4000);
  }

  // ── 2FA Enrolment Modal ──
  // Shows the TOTP secret + provisioning URI, lets the user enter a code,
  // calls /auth/2fa/confirm, then shows recovery codes.
  async function open2faEnrolmentModal(loginRes) {
    const ticket = loginRes.enrolment_ticket;
    const overlay = document.createElement('div');
    overlay.className = 'mm-modal-backdrop';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;z-index:9999;';
    overlay.innerHTML = `
      <div class="mm-modal" style="max-width:480px;background:#fff;border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,.2);overflow:hidden;">
        <div style="background:#009879;color:#fff;padding:14px 18px;font-size:15px;font-weight:700;">🔐 SETUP TWO-FACTOR AUTHENTICATION</div>
        <div style="padding:18px;font-size:13.5px;color:#1e293b;">
          <p style="margin:0 0 12px;">Your role requires 2FA. Set up Google Authenticator:</p>
          <div style="background:#f1f5f9;border-radius:6px;padding:12px;margin-bottom:14px;">
            <div style="font-weight:700;margin-bottom:6px;">Step 1 — Add to Google Authenticator</div>
            <div style="font-size:12px;word-break:break-all;" id="2fa-setup-info">Generating secret…</div>
          </div>
          <div style="margin-bottom:14px;">
            <label style="display:block;font-weight:700;margin-bottom:6px;">Step 2 — Enter 6-digit code from your app</label>
            <input type="text" id="2fa-confirm-code" maxlength="6" inputmode="numeric" pattern="[0-9]*"
              style="width:100%;padding:10px;border:2px solid #e2e8f0;border-radius:6px;font-size:18px;text-align:center;letter-spacing:4px;"
              placeholder="••••••" autocomplete="one-time-code" />
          </div>
          <div id="2fa-recovery-box" style="display:none;background:#fffbeb;border:1px solid #fcd34d;border-radius:6px;padding:12px;margin-bottom:14px;">
            <div style="font-weight:700;color:#92400e;margin-bottom:6px;">⚠️ RECOVERY CODES — Save these NOW!</div>
            <div id="2fa-recovery-codes" style="font-size:12px;line-height:1.8;word-break:break-all;"></div>
          </div>
          <div style="display:flex;gap:8px;justify-content:flex-end;">
            <button class="mm-btn mm-btn-default" id="2fa-cancel">Cancel</button>
            <button class="mm-btn mm-btn-primary" id="2fa-confirm-btn" style="background:#009879;border-color:#009879;">Confirm & Enable</button>
          </div>
        </div>
      </div>`;
    document.body.appendChild(overlay);

    // Fetch the TOTP secret + provisioning URI
    // The enrolment ticket is a signed token — send it as X-Auth-Token so
    // TenantScopeMiddleware can verify it and set auth_user for the controller.
    const setupUrl = (window.location.origin || '') + '/api/auth/2fa/setup';
    const setupFetch = await window.fetch(setupUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'X-Auth-Token': ticket,
      },
      body: JSON.stringify({}),
    });
    const setupData = await setupFetch.json();
    if (!setupFetch.ok) {
      overlay.querySelector('#2fa-setup-info').textContent = setupData.error || 'Setup failed. Please try logging in again.';
      return;
    }
    overlay.querySelector('#2fa-setup-info').innerHTML =
      `<div><b>Account:</b> ${esc(setupData.account || '')}</div>` +
      `<div><b>Issuer:</b> ${esc(setupData.issuer || '')}</div>` +
      `<div style="margin-top:6px;"><b>Secret:</b> <code style="font-size:11px;word-break:break-all;">${esc(setupData.secret || '')}</code></div>` +
      `<div style="margin-top:6px;"><b>Or scan:</b> <a href="${esc(setupData.otpauth_uri || '')}" target="_blank">otpauth:// URI</a></div>`;

    // Confirm button
    overlay.querySelector('#2fa-confirm-btn').onclick = async () => {
      const code = overlay.querySelector('#2fa-confirm-code').value.trim();
      if (code.length !== 6) {
        showToast('Enter a 6-digit code.', true);
        return;
      }
      const confirmUrl = (window.location.origin || '') + '/api/auth/2fa/confirm';
      const confirmRes = await window.fetch(confirmUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-Auth-Token': ticket,
        },
        body: JSON.stringify({ code }),
      });
      const confirmData = await confirmRes.json();
      if (!confirmRes.ok) {
        showToast(confirmData.error || 'Code did not match. Try the next code.', true);
        return;
      }
      // Show recovery codes
      const recoveryBox = overlay.querySelector('#2fa-recovery-box');
      const recoveryCodes = overlay.querySelector('#2fa-recovery-codes');
      recoveryBox.style.display = 'block';
      recoveryCodes.textContent = (confirmData.recovery_codes || []).join('\n');
      overlay.querySelector('#2fa-confirm-btn').textContent = '✓ Enabled — Click to continue';
      overlay.querySelector('#2fa-confirm-btn').onclick = () => {
        overlay.remove();
        showToast('2FA enabled! Please log in again.', false);
        renderApp();
      };
      showToast('2FA enabled! Save your recovery codes.', false);
    };

    // Cancel
    overlay.querySelector('#2fa-cancel').onclick = () => {
      overlay.remove();
      showToast('2FA setup cancelled. You can set it up later.', true);
    };
  }

  // ── 2FA Verification Modal ──
  // Shows a TOTP code input, calls /auth/2fa/verify, then logs in.
  function open2faVerifyModal(loginRes) {
    const challenge = loginRes.challenge;
    const overlay = document.createElement('div');
    overlay.className = 'mm-modal-backdrop';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;z-index:9999;';
    overlay.innerHTML = `
      <div class="mm-modal" style="max-width:400px;background:#fff;border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,.2);overflow:hidden;">
        <div style="background:#3c8dbc;color:#fff;padding:14px 18px;font-size:15px;font-weight:700;">🔐 VERIFY YOUR IDENTITY</div>
        <div style="padding:18px;font-size:13.5px;color:#1e293b;">
          <p style="margin:0 0 12px;">Enter the 6-digit code from your authenticator app:</p>
          <input type="text" id="2fa-verify-code" maxlength="6" inputmode="numeric" pattern="[0-9]*"
            style="width:100%;padding:12px;border:2px solid #e2e8f0;border-radius:6px;font-size:20px;text-align:center;letter-spacing:6px;"
            placeholder="••••••" autocomplete="one-time-code" />
          <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">
            <button class="mm-btn mm-btn-default" id="2fa-verify-cancel">Cancel</button>
            <button class="mm-btn mm-btn-primary" id="2fa-verify-btn" style="background:#3c8dbc;border-color:#3c8dbc;">Verify</button>
          </div>
        </div>
      </div>`;
    document.body.appendChild(overlay);

    const codeInput = overlay.querySelector('#2fa-verify-code');
    codeInput.focus();

    overlay.querySelector('#2fa-verify-btn').onclick = async () => {
      const code = codeInput.value.trim();
      if (code.length !== 6) {
        showToast('Enter a 6-digit code.', true);
        return;
      }
      const verifyUrl = (window.location.origin || '') + '/api/auth/2fa/verify';
      const verifyRes = await window.fetch(verifyUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-Auth-Token': challenge,
        },
        body: JSON.stringify({ code }),
      });
      const verifyData = await verifyRes.json();
      if (!verifyRes.ok) {
        showToast(verifyData.error || 'Invalid code. Try again.', true);
        return;
      }
      state.token = verifyData.access || verifyData.token;
      state.user = verifyData.user;
      safeStorageSet('neev_mfi_access_token', state.token);
      safeStorageSet('neev_mfi_user', JSON.stringify(state.user));
      overlay.remove();
      showToast('Welcome back!', false);
      state.openGroups = {};
      navigateTo('/dashboard');
    };

    overlay.querySelector('#2fa-verify-cancel').onclick = () => {
      overlay.remove();
      showToast('Verification cancelled.', true);
    };

    codeInput.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter') overlay.querySelector('#2fa-verify-btn').click();
    });
  }

  function fmtMoney(v) {
    const cleaned = typeof v === 'string' ? v.replace(/[₹,\s]/g, '') : v;
    const rawNum = Number(cleaned || 0);
    const num = Number.isFinite(rawNum) ? rawNum : 0;
    return '₹' + num.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  function esc(str) {
    return String(str === null || str === undefined ? '' : str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function sanitizeUserText(val) {
    if (val === null || val === undefined) return '';
    return String(val)
      .replace(/\0/g, '')
      .replace(/<\s*script[^>]*>[\s\S]*?<\s*\/\s*script\s*>/gi, '')
      .replace(/<\s*\/?\s*(script|iframe|object|embed|applet|meta|link|style|base|form|svg|math)[^>]*>/gi, '')
      .replace(/\bon[a-z]{2,25}\s*=/gi, '')
      .replace(/(javascript|vbscript|livescript)\s*:/gi, 'blocked:')
      .replace(/data\s*:\s*(text\/html|application\/xhtml)/gi, 'blocked:')
      .replace(/<[^>]+>/g, '')
      .trim();
  }

  function safeImageSrc(src, fallback) {
    const raw = String(src || '').trim();
    if (!raw) return fallback ? esc(fallback) : '';
    const lower = raw.toLowerCase();
    if (
      lower.startsWith('javascript:') ||
      lower.startsWith('vbscript:') ||
      lower.startsWith('data:text/html') ||
      lower.includes('<script') ||
      lower.includes('onerror') ||
      lower.includes('onload') ||
      lower.includes('onclick')
    ) {
      return fallback ? esc(fallback) : '';
    }
    if (lower.startsWith('data:')) {
      if (!/^data:image\/(png|jpeg|jpg|webp|gif|svg\+xml)(;base64|;utf8|,)/i.test(raw)) {
        return fallback ? esc(fallback) : '';
      }
      return esc(raw);
    }
    if (lower.startsWith('http://') || lower.startsWith('https://') || raw.startsWith('/') || raw.startsWith('./')) {
      return esc(raw);
    }
    return fallback ? esc(fallback) : '';
  }

  function validateClientImageUpload(file, maxBytes = 1048576) {
    if (!file) throw new Error('No file selected.');
    const name = String(file.name || '').toLowerCase();
    const parts = name.split('.');
    const badExts = ['php','exe','sh','bat','cmd','js','jsp','asp','aspx','py','html','htm','svg','dll','elf'];
    for (let i = 1; i < parts.length; i++) {
      if (badExts.includes(parts[i])) {
        throw new Error('Security Guard: Malicious or executable file extension (.' + parts[i] + ') is blocked.');
      }
    }
    const ext = parts.length > 1 ? '.' + parts[parts.length - 1] : '';
    const allowedExts = ['.png', '.jpg', '.jpeg', '.webp'];
    if (!allowedExts.includes(ext)) {
      throw new Error('Security Guard: Only PNG, JPG, JPEG, and WEBP image files are permitted.');
    }
    const allowedMimes = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp'];
    if (file.type && !allowedMimes.includes(file.type.toLowerCase())) {
      throw new Error('Security Guard: Invalid MIME type (' + file.type + ').');
    }
    if (file.size <= 0 || file.size > maxBytes) {
      throw new Error('Security Guard: File size must be between 1 byte and ' + Math.round(maxBytes / 1024) + ' KB.');
    }
    return true;
  }


