  function renderRfIcon(name, size = 18, className = '') {
    const ic = RF_FA[name] || RF_FA.radio;
    return `<svg class="rfIco${className ? ' ' + className : ''}" viewBox="${ic[0]}" width="${size}" height="${size}" fill="currentColor" aria-hidden="true" focusable="false"><path d="${ic[1]}"/></svg>`;
  }

  // Every submenu item maps to its NEEV 4D functional page route.


  // V180 behaviour: every treeview group is expanded on entry, so the operator
  // can see the whole menu tree at a glance (matches Umang's `treeview menu-open`).
  function allGroupsOpen() {
    const out = {};
    (NAVIGATION_TREE || []).forEach((g) => { if (Array.isArray(g.children) && g.children.length) out[g.id] = true; });
    return out;
  }

  function getEffectiveNavigationTree(forceTree = null) {
    const sc = state.superConfig || {};
    const ov = sc.menu_overrides || {};
    const customList = Array.isArray(sc.custom_menus) ? sc.custom_menus : [];
    const sourceTree = forceTree || NAVIGATION_TREE;
    const baseCloned = sourceTree.map((item, idx) => {
      if (item.header) {
        return { ...item, order: idx, visible: true };
      }
      const mOv = ov[item.id] || {};
      const children = Array.isArray(item.children)
        ? item.children.map((sub) => {
            const sKey = `${item.id}:${sub.path}`;
            const sOv = ov[sKey] || {};
            return {
              ...sub,
              superTab: sub.superTab,
              label: sOv.label !== undefined && sOv.label !== '' ? sOv.label : sub.label,
              visible: sOv.visible !== undefined ? !!sOv.visible : true,
            };
          }).filter((s) => s.visible !== false)
        : undefined;
      return {
        ...item,
        label: mOv.label !== undefined && mOv.label !== '' ? mOv.label : item.label,
        icon: mOv.icon !== undefined && mOv.icon !== '' ? mOv.icon : item.icon,
        visible: mOv.visible !== undefined ? !!mOv.visible : true,
        order: mOv.order !== undefined ? Number(mOv.order) : idx,
        children,
      };
    });
    const combined = [...baseCloned, ...customList.map((cm, cIdx) => ({
      id: cm.id || `custom_${cIdx}`,
      label: cm.label || 'CUSTOM MENU',
      icon: cm.icon || '★',
      path: cm.path || '/customer',
      visible: cm.visible !== false,
      order: 100 + cIdx,
      children: Array.isArray(cm.children) ? cm.children : undefined,
    }))];
    return combined.filter((m) => {
      if (m.visible === false) return false;
      return true;
    }).sort((a, b) => a.order - b.order);
  }


  function generateCustomBrandSvgLogo(titleText, subtitleText, primaryColor = '#16a34a', badgeSymbol = '₹') {
    const t = String(titleText || 'NEEV MICROFINANCE CARE').trim().toUpperCase().slice(0, 22);
    const s = String(subtitleText || 'MICROFINANCE CORE BANKING').trim().toUpperCase().slice(0, 32);
    const c = String(primaryColor || '#16a34a').trim();
    const sym = String(badgeSymbol || '₹').trim().slice(0, 2);
    const safeT = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const safeS = s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const safeSym = sym.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const svgBanner = `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="84" viewBox="0 0 320 84">
      <defs>
        <linearGradient id="bgGrad" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stop-color="${c}"/>
          <stop offset="100%" stop-color="#0f172a"/>
        </linearGradient>
      </defs>
      <rect x="2" y="2" width="316" height="80" rx="12" fill="#ffffff" stroke="${c}" stroke-width="2.5"/>
      <rect x="12" y="12" width="60" height="60" rx="14" fill="url(#bgGrad)"/>
      <circle cx="42" cy="42" r="23" fill="none" stroke="#ffffff" stroke-width="1.5" stroke-dasharray="3,2" opacity="0.75"/>
      <text x="42" y="53" text-anchor="middle" font-family="Arial, sans-serif" font-size="32" font-weight="900" fill="#ffffff">${safeSym}</text>
      <text x="84" y="42" font-family="Poppins, Arial, sans-serif" font-size="20" font-weight="900" fill="#0f172a" letter-spacing="0.4">${safeT}</text>
      <text x="84" y="62" font-family="Poppins, Arial, sans-serif" font-size="10.5" font-weight="800" fill="${c}" letter-spacing="0.8">${safeS}</text>
    </svg>`;
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svgBanner);
  }

