  function getBaseFormFieldsForRoute(routePath) {
    if (routePath === '/customer') return DEFAULT_CUSTOMER_5TAB_FIELDS.map((f) => ({ ...f, options: f.options ? [...f.options] : undefined }));
    if (routePath === '/loanSettlement') return DEFAULT_SETTLEMENT_FIELDS.map((f) => ({ ...f, options: f.options ? [...f.options] : undefined }));
    const cfg = routeCfg(routePath) || {};
    return (cfg.fields || []).map((f) => ({ ...f, options: f.options ? [...f.options] : undefined }));
  }

  async function refreshLiveCatalog() {
    if (!state.token) return;
    try {
      const [plansRes, branchesRes, centersRes, staffRes] = await Promise.all([
        apiCall('/resources/loan-plans', { params: { page_size: 200 } }).catch(() => null),
        apiCall('/resources/branches', { params: { page_size: 200 } }).catch(() => null),
        apiCall('/resources/centers', { params: { page_size: 200 } }).catch(() => null),
        apiCall('/resources/employees', { params: { page_size: 200 } }).catch(() => null),
      ]);
      state.liveCatalog = {
        plans: ((plansRes && plansRes.results) || []).map((p) => p.plan_name).filter(Boolean),
        branches: ((branchesRes && branchesRes.results) || []).map((b) => b.name).filter(Boolean),
        centers: ((centersRes && centersRes.results) || []).map((c) => c.name).filter(Boolean),
        employees: ((staffRes && staffRes.results) || []).filter((emp) => emp && (emp.name || emp.user_code)),
      };
    } catch (_e) {
      // Non-fatal
    }
  }

  function hydrateDynamicSelectOptions(fieldsList) {
    const cat = state.liveCatalog || {};
    return (fieldsList || []).map((f) => {
      if (!f || f.type !== 'select' || !Array.isArray(f.options)) return f;
      const mergeUnique = (liveArr, staticArr) => {
        const seen = new Set();
        const out = [];
        for (const item of [...(liveArr || []), ...(staticArr || [])]) {
          const s = String(item || '').trim();
          if (s && !seen.has(s.toUpperCase())) {
            seen.add(s.toUpperCase());
            out.push(s);
          }
        }
        return out;
      };
      if (f.name === 'plan_name' && cat.plans && cat.plans.length > 0) {
        return { ...f, options: mergeUnique(cat.plans, f.options) };
      }
      if (f.name === 'branch_name' && cat.branches && cat.branches.length > 0) {
        return { ...f, options: mergeUnique(cat.branches, f.options) };
      }
      if (f.name === 'center_name' && cat.centers && cat.centers.length > 0) {
        return { ...f, options: mergeUnique(cat.centers, f.options) };
      }
      return f;
    });
  }

  function getEffectiveFormFields(routePath, fallbackFields) {
    const ovMap = (state.superConfig && state.superConfig.form_field_overrides) || {};
    const customList = ovMap[routePath];
    if (Array.isArray(customList) && customList.length > 0) {
      return hydrateDynamicSelectOptions(customList.filter((f) => f && f.enabled !== false));
    }
    const base = fallbackFields || getBaseFormFieldsForRoute(routePath);
    return hydrateDynamicSelectOptions((base || []).filter((f) => f && f.enabled !== false));
  }

