  function findParentGroupForPath(path) {
    const canon = resolveRoute(path);
    const tree = NAVIGATION_TREE;
    for (const item of tree) {
      if (Array.isArray(item.children) && item.children.some((c) => c.path === path || resolveRoute(c.path) === canon)) {
        return item.id;
      }
    }
    return null;
  }

  function findParentLabelAndSubLabel(path) {
    const tree = getEffectiveNavigationTree();
    for (const item of tree) {
      if (item.path === path) return { parent: null, current: item.label };
      if (Array.isArray(item.children)) {
        const hit = item.children.find((c) => c.path === path);
        if (hit) return { parent: item.label, current: hit.label };
      }
    }
    const cfg = routeCfg(path);
    return { parent: null, current: (cfg && cfg.title) || path.replace('/', '').toUpperCase() };
  }

  function showGlobalLoader(label) {
    const sc = state.superConfig || {};
    const lStyle = String(sc.loader_style || 'BOTH_BAR_AND_SPINNER').toUpperCase();
    if (lStyle === 'NONE') return;
    const lColor = sc.loader_color || '#681827';
    const effectiveLabel = label || sc.loader_text || 'Processing request…';
    document.documentElement.style.setProperty('--nmfa-loader-color', lColor);

    state.globalLoading = true;
    state.globalLoadingLabel = effectiveLabel;

    // 1. Top Shimmer Progress Bar
    let barEl = document.getElementById('nmfa-top-loadbar');
    if (!barEl) {
      barEl = document.createElement('div');
      barEl.id = 'nmfa-top-loadbar';
      barEl.className = 'nmfaTopLoadBarWrap';
      barEl.innerHTML = '<div class="nmfaTopLoadBarFill"></div>';
      document.body.appendChild(barEl);
    }
    const showTopBar = ['BOTH_BAR_AND_SPINNER', 'TOP_LOAD_BAR', 'DUAL_LASER_BAR', 'PULSE_SHIELD', 'THREE_DOTS_WAVE', 'DUAL_ORBIT_RING', 'TOP_PILL_TOAST_LOADER'].includes(lStyle);
    barEl.style.display = showTopBar ? 'block' : 'none';

    // 2. Bottom Laser Bar
    let botEl = document.getElementById('nmfa-bottom-loadbar');
    if (!botEl) {
      botEl = document.createElement('div');
      botEl.id = 'nmfa-bottom-loadbar';
      botEl.className = 'nmfaBottomLaserBar';
      botEl.innerHTML = '<div class="nmfaTopLoadBarFill"></div>';
      document.body.appendChild(botEl);
    }
    botEl.style.display = (lStyle === 'DUAL_LASER_BAR') ? 'block' : 'none';

    // 3. Striped Top Progress Banner
    let stripedEl = document.getElementById('nmfa-striped-banner');
    if (!stripedEl) {
      stripedEl = document.createElement('div');
      stripedEl.id = 'nmfa-striped-banner';
      stripedEl.className = 'nmfaStripedTopBanner';
      document.body.appendChild(stripedEl);
    }
    if (lStyle === 'STRIPED_PROGRESS_BANNER') {
      stripedEl.innerHTML = `⚡ ${esc(effectiveLabel)} — 88% SYNCED`;
      stripedEl.style.display = 'flex';
    } else {
      stripedEl.style.display = 'none';
    }

    // 4. Floating Top Pill Toast Loader
    let pillEl = document.getElementById('nmfa-top-pill-loader');
    if (!pillEl) {
      pillEl = document.createElement('div');
      pillEl.id = 'nmfa-top-pill-loader';
      pillEl.className = 'nmfaTopPillToast';
      document.body.appendChild(pillEl);
    }
    if (lStyle === 'TOP_PILL_TOAST_LOADER') {
      pillEl.innerHTML = `<span class="nmfaSpinnerRing" style="width:16px !important;height:16px !important;border-width:2px !important;"></span><span>⚡ ${esc(effectiveLabel)}</span>`;
      pillEl.style.display = 'inline-flex';
    } else {
      pillEl.style.display = 'none';
    }

    // 5. Center Modal Card (Spinner / Pulse Shield / 3-Dots Wave / Dual Orbit)
    let el = document.getElementById('nmfa-global-loader');
    if (!el) {
      el = document.createElement('div');
      el.id = 'nmfa-global-loader';
      el.className = 'nmfaGlobalLoader';
      el.setAttribute('role', 'status');
      el.setAttribute('aria-live', 'polite');
      document.body.appendChild(el);
    }
    if (['TOP_LOAD_BAR', 'STRIPED_PROGRESS_BANNER', 'DUAL_LASER_BAR', 'TOP_PILL_TOAST_LOADER'].includes(lStyle)) {
      el.style.setProperty('display', 'none', 'important');
      return;
    }
    if (lStyle === 'PULSE_SHIELD') {
      el.innerHTML = `<div class="nmfaGlobalLoaderCard" style="border-top-color:${esc(lColor)} !important;"><span class="nmfaPulseShieldBadge" style="background:${esc(lColor)};">${esc(sc.logo_text || '₹')}</span><b>${esc(effectiveLabel)}</b></div>`;
    } else if (lStyle === 'THREE_DOTS_WAVE') {
      el.innerHTML = `<div class="nmfaGlobalLoaderCard" style="border-top-color:${esc(lColor)} !important;"><span class="nmfaWaveDotsWrap"><span class="nmfaWaveDot"></span><span class="nmfaWaveDot"></span><span class="nmfaWaveDot"></span></span><b>${esc(effectiveLabel)}</b></div>`;
    } else if (lStyle === 'DUAL_ORBIT_RING') {
      el.innerHTML = `<div class="nmfaGlobalLoaderCard" style="border-top-color:${esc(lColor)} !important;"><span class="nmfaDualOrbitWrap"><span class="nmfaDualOrbitOuter"></span><span class="nmfaDualOrbitInner"></span></span><b>${esc(effectiveLabel)}</b></div>`;
    } else {
      el.innerHTML = `<div class="nmfaGlobalLoaderCard" style="border-top-color:${esc(lColor)} !important;"><span class="nmfaSpinnerRing" style="border-top-color:${esc(lColor)} !important;" aria-hidden="true"></span><b>${esc(effectiveLabel)}</b></div>`;
    }
    el.style.display = 'grid';
  }

  function hideGlobalLoader() {
    state.globalLoading = false;
    if (window.__nmfaLoaderSafetyTimer) {
      clearTimeout(window.__nmfaLoaderSafetyTimer);
      window.__nmfaLoaderSafetyTimer = null;
    }
    const el = document.getElementById('nmfa-global-loader');
    const barEl = document.getElementById('nmfa-top-loadbar');
    const botEl = document.getElementById('nmfa-bottom-loadbar');
    const stripedEl = document.getElementById('nmfa-striped-banner');
    const pillEl = document.getElementById('nmfa-top-pill-loader');
    if (el) el.style.setProperty('display', 'none', 'important');
    if (barEl) barEl.style.display = 'none';
    if (botEl) botEl.style.display = 'none';
    if (stripedEl) stripedEl.style.display = 'none';
    if (pillEl) pillEl.style.display = 'none';
  }

  async function apiCall(endpoint, { method = 'GET', body = null, params = {} } = {}) {
    showGlobalLoader(method === 'GET' ? 'Loading records…' : 'Processing request…');
    if (window.__nmfaLoaderSafetyTimer) clearTimeout(window.__nmfaLoaderSafetyTimer);
    window.__nmfaLoaderSafetyTimer = setTimeout(() => hideGlobalLoader(), 1200);
    try {
      if (typeof window.__handleMockApi === 'function' && window.__CANVAS_STANDALONE_MODE__) {
        const mockData = await window.__handleMockApi(endpoint, method, body || {}, params || {});
        hideGlobalLoader();
        return mockData;
      }
      const rawOrigin = (window.location && typeof window.location.origin === 'string') ? window.location.origin : '';
      if (!/^https?:\/\//i.test(rawOrigin)) throw new Error('A secure HTTP(S) backend origin is required. Offline localhost fallbacks are disabled.');
      const baseOrigin = rawOrigin;
      const url = new URL('/api' + endpoint, baseOrigin);
      Object.entries(params || {}).forEach(([k, v]) => {
        if (v !== undefined && v !== null && v !== '') url.searchParams.set(k, v);
      });
      const headers = { 'Content-Type': 'application/json' };
      if (state.token) {
        headers['Authorization'] = 'Bearer ' + state.token;
        headers['X-Auth-Token'] = state.token;
      }
      let res;
      try {
        res = await window.fetch(url.toString(), {
          method,
          headers,
          body: body ? JSON.stringify(body) : undefined,
        });
      } catch (fetchErr) {
        if (typeof window.__handleMockApi === 'function' && (window.__CANVAS_STANDALONE_MODE__ || window.__NEEV_DEMO_MODE__)) {
          const fallbackData = await window.__handleMockApi(endpoint, method, body || {}, params || {});
          hideGlobalLoader();
          return fallbackData;
        }
        throw fetchErr;
      }
      const isAuthEndpoint = endpoint.startsWith('/auth/');
      if (res.status === 401 && !isAuthEndpoint && !window.__CANVAS_STANDALONE_MODE__) {
        state.token = '';
        state.user = null;
        safeStorageRemove('neev_mfi_access_token');
        safeStorageRemove('neev_mfi_user');
        hideGlobalLoader();
        renderApp();
        throw new Error('Session expired. Please sign in again.');
      }
      const data = await res.json().catch(() => ({}));
      // 2FA enrolment / verification responses return 403 with a 'code' field
      // (e.g. 2FA_ENROLMENT_REQUIRED, 2FA_REQUIRED). Return the data so the
      // caller can handle the multi-step flow instead of treating it as an error.
      if (!res.ok && data.code === '2FA_ENROLMENT_REQUIRED') {
        hideGlobalLoader();
        return data;
      }
      if (!res.ok) {
        hideGlobalLoader();
        throw new Error(data.error || `Operation failed (HTTP ${res.status})`);
      }
      hideGlobalLoader();
      return data;
    } finally {
      hideGlobalLoader();
    }
  }

  async function loadDashboard() {
    try {
      const data = await apiCall('/dashboard', { params: { branch: state.dashboardBranch } });
      state.dashboardData = data;
      renderApp();
    } catch (e) {
      showToast(e.message, true);
    }
  }

  async function loadModuleRoute(path) {
    const cfg = routeCfg(path);
    if (!cfg) return;
    try {
      if (cfg.specialView === 'rolePermissionMatrix') {
        state.specialData = await apiCall('/role-permissions', { params: { role_id: state.selectedRoleId } });
      } else if (cfg.specialView === 'voucherToolbar' || cfg.specialView === 'voucherForm') {
        const rowsV = await apiCall('/resources/vouchers', { params: { page_size: 25 } }).catch(() => ({ results: [] }));
        const ledV = await apiCall('/resources/ledgers', { params: { page_size: 200 } }).catch(() => ({ results: [] }));
        const ledgers = (ledV && ledV.results) || [];
        state.specialData = {
          vouchers: (rowsV && rowsV.results) || [],
          ledgers,
          cashLedgers: ledgers.filter((l) => /^CASH IN HAND$/i.test(l.name || '')),
          bankLedgers: ledgers.filter((l) => /BANK ACCOUNT|BANK/i.test(l.name || '')),
          allLedgers: ledgers,
          freshForm: state.voucherFormReset !== false,
        };
        state.voucherFormReset = false;
      } else if (cfg.specialView === 'accountingOverview') {
        const [cbOv, plOv, ledOv] = await Promise.all([
          apiCall('/accounting/cashbook', { params: { branch: state.moduleFilters.branch_name || '', date: state.moduleFilters.date_from || '' } }).catch(() => null),
          apiCall('/accounting/profit-loss', { params: { branch: state.moduleFilters.branch_name || '' } }).catch(() => null),
          apiCall('/resources/ledgers', { params: { page_size: 200 } }).catch(() => null),
        ]);
        state.specialData = {
          cashbook: cbOv,
          pl: plOv,
          bankLedgers: ((ledOv && ledOv.results) || []).filter((l) => /BANK|CASH/i.test(l.name || '')),
        };
      } else if (cfg.specialView === 'cashbook') {
        state.specialData = await apiCall('/accounting/cashbook', { params: { branch: state.moduleFilters.branch_name, date: state.moduleFilters.date_from } });
      } else if (cfg.specialView === 'trialbalance') {
        const [tbData, bsData, reconData, auditData, npaData] = await Promise.all([
          apiCall('/accounting/trial-balance', { params: { branch: state.moduleFilters.branch_name } }),
          apiCall('/accounting/balance-sheet', { params: { branch: state.moduleFilters.branch_name } }).catch(() => null),
          apiCall('/accounting/reconciliation', { params: { branch: state.moduleFilters.branch_name } }).catch(() => null),
          apiCall('/audit/verify-chain').catch(() => null),
          apiCall('/loans/npa-classification', { params: { branch: state.moduleFilters.branch_name } }).catch(() => null),
        ]);
        state.specialData = { ...tbData, balanceSheet: bsData, reconciliation: reconData, auditChain: auditData, npaReport: npaData };
      } else if (cfg.specialView === 'fundingCapital') {
        const [posData, ledData, bankRec, cashRec] = await Promise.all([
          apiCall('/accounting/funding-position'),
          apiCall('/accounting/owner-funds'),
          apiCall('/resources/bank-accounts', { params: { page_size: 100 } }).catch(() => null),
          apiCall('/resources/vouchers', { params: { voucher_type: 'RECEIPT', page_size: 20 } }).catch(() => null),
        ]);
        state.specialData = { position: posData, ledgers: ledData, bankAccounts: (bankRec && bankRec.results) || [], recentReceipts: (cashRec && cashRec.results) || [] };
      } else if (cfg.specialView === 'profitloss') {
        state.specialData = await apiCall('/accounting/profit-loss', { params: { branch: state.moduleFilters.branch_name } });
      } else if (cfg.specialView === 'eodClosingView') {
        const cbEod = await apiCall('/accounting/cashbook', { params: { branch: state.eodBranch || '' } }).catch(() => null);
        if (cbEod && cbEod.cash_records) {
          state.eodSystemCash = Number(cbEod.cash_records.closing_balance || 0);
        }
      }
      const activeFilters = {};
      Object.entries(state.moduleFilters || {}).forEach(([k, v]) => {
        if (v !== '' && v !== null && v !== undefined) activeFilters[k] = v;
      });
      const queryParams = { ...(cfg.defaultFilters || {}), ...activeFilters };
      // LOAN TOPUP has its own register endpoint (previous-loan payoff snapshot
      // is computed server-side, so the flat resource list cannot serve it).
      if (cfg.umangTopupView) {
        state.moduleData = await apiCall('/loan-topups', {
          params: {
            branch_name: state.moduleFilters.branch_name || '',
            member_code: state.moduleFilters.member_code || '',
            search: state.moduleFilters.search || '',
            page: state.moduleFilters.page || 1,
            page_size: state.moduleFilters.page_size || 10,
          },
        });
        if (!state.topupContext || !(state.topupContext.branches || []).length) {
          await loadTopupContext(state.moduleFilters.branch_name || '');
        }
      } else if (cfg.umangIndView) {
        // INDIVIDUALLOAN register. SELECT STATUS in the reference maps to the
        // real loan statuses, so the mapping is applied here (never in SQL).
        const _stMap = {
          Pending: 'PENDING_APPROVAL',
          Approved: 'APPROVED,DISBURSED,ACTIVE,COMPLETED,SETTLED',
          Reject: 'REJECTED',
        };
        const _st = _stMap[String(state.moduleFilters.status_label || '')] || '';
        // `/addLoan` is the individual-loan register: it lists every member-level
        // loan (individual loans only — group loan features removed),
        // because the same member loan can be PERSONAL / BUSINESS / PRODUCT.
        const params = {
          branch_name: state.moduleFilters.branch_name || '',
          center_name: state.moduleFilters.center_name || '',
          staff_name: state.moduleFilters.staff_name || '',
          member_query: state.moduleFilters.member_code || state.moduleFilters.member_label || '',
          status_list: _st,
          search: state.moduleFilters.search || '',
          page: state.moduleFilters.page || 1,
          page_size: state.moduleFilters.page_size || 10,
        };
        state.moduleData = await apiCall(`/resources/${cfg.resource}`, { params });
        if (!state.indContext || !(state.indContext.branches || []).length) {
          await loadIndividualContext();
        }
      } else if (cfg.customerLoanView) {
        await loadCustomerLoanDetails();
      } else if (cfg.specialView === 'roleListView') {
        await loadRoleList();
      } else if (cfg.specialView === 'permissionListView') {
        await loadPermissionList();
      } else if (cfg.resource) {
        state.moduleData = await apiCall(`/resources/${cfg.resource}`, { params: queryParams });
      }
      renderApp();
    } catch (e) {
      // A failed register read must never leave the previous screen's rows on
      // display — the operator would action the wrong record.
      state.moduleData = { results: [], count: 0, page: 1, page_size: state.moduleFilters.page_size || 10, total_pages: 1 };
      renderApp();
      showToast(e.message, true);
    }
  }

  function navigateTo(path) {
    if (['/group', '/memberGroup', '/memberCgtGrt', '/customercgt', '/customergroup', '/groupMemberDisbursement', '/groupDisbursement', '/groupEmiCollection'].includes(path)) {
      path = resolveRoute(path);
      if (!ROUTE_CONFIG[path]) path = '/individualDisburseList';
    }
    state.currentPath = path;
    state.adminDropdownOpen = false;
    if (typeof window !== 'undefined' && window.innerWidth <= 768) {
      state.sidebarCollapsed = true;
    }
    {
      const parentGid = findParentGroupForPath(path);
      state.openGroups = parentGid ? { [parentGid]: true } : {};
    }
    const navCfg = routeCfg(path) || {};
    state.moduleFilters = { search: '', branch_name: '', status: '', staff_name: '', collection_day: '', recovery_type: '', due_scope: '', date_from: '', date_to: '', page: 1, page_size: 25, ...(navCfg.defaultFilters || {}) };
    state.specialData = null;
    if (path === '/dashboard' || path === '/') {
      loadDashboard();
    } else {
      loadModuleRoute(path);
    }
    renderApp();
    // Always reset content scroll to top so pages never open scrolled up or half-cut under header
    try {
      window.scrollTo(0, 0);
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
      const mc = document.querySelector('.mm-content');
      if (mc) mc.scrollTop = 0;
    } catch (_e) {}
  }

  // SVG Donut Chart Generator
  function renderDonutSvg(items, title) {
    const total = items.reduce((acc, it) => acc + Math.max(0, Number(it.value || 0)), 0) || 1;
    let cumulative = 0;
    const radius = 58;
    const circumference = 2 * Math.PI * radius;
    const circles = items.map((it) => {
      const val = Math.max(0, Number(it.value || 0));
      const frac = val / total;
      const dash = frac * circumference;
      const offset = -cumulative * circumference;
      cumulative += frac;
      return `<circle r="${radius}" cx="80" cy="80" fill="transparent" stroke="${it.color}" stroke-width="24" stroke-dasharray="${dash.toFixed(2)} ${circumference.toFixed(2)}" stroke-dashoffset="${offset.toFixed(2)}" transform="rotate(-90 80 80)"></circle>`;
    }).join('');

    const legend = items.map((it) => `
      <div style="display:flex;align-items:center;justify-content:space-between;font-size:12px;padding:3px 0;">
        <span style="display:flex;align-items:center;gap:6px;font-weight:600;">
          <span style="width:11px;height:11px;border-radius:2px;background:${it.color};display:inline-block;"></span>
          ${esc(it.label)}
        </span>
        <strong>${fmtMoney(it.value)}</strong>
      </div>
    `).join('');

    return `
      <div class="mm-box">
        <div class="mm-box-header"><span class="mm-box-title">${esc(title)}</span></div>
        <div class="mm-box-body" style="display:flex;align-items:center;gap:18px;flex-wrap:wrap;">
          <svg width="160" height="160" viewBox="0 0 160 160">
            <circle r="${radius}" cx="80" cy="80" fill="transparent" stroke="#ecf0f5" stroke-width="24"></circle>
            ${circles}
            <text x="80" y="84" text-anchor="middle" font-size="11" font-weight="700" fill="#333">PORTFOLIO</text>
          </svg>
          <div style="flex:1;min-width:180px;">${legend}</div>
        </div>
      </div>
    `;
  }

