  // ==========================================================================
  // FUNDING & CAPITAL — owner funds, borrowings, liquidity and lending head-room
  // ==========================================================================
  function renderFundingCapitalView() {
    const sd = state.specialData || {};
    const pos = sd.position || {};
    const led = sd.ledgers || {};
    const heads = led.owner_fund_heads || [];
    const banks = sd.bankAccounts || [];
    const fmt = (v) => fmtMoney(v);
    const num = (v) => Number(v || 0);

    const owned = num(pos.owned_funds), borrowed = num(pos.borrowed_funds), totalFunds = num(pos.total_funds);
    const cash = num(pos.cash_in_hand), bank = num(pos.bank_balance);
    const outstanding = num(pos.outstanding_portfolio), headRoom = num(pos.lending_head_room);
    const canLend = num(pos.can_lend_now), maxPort = num(pos.max_safe_portfolio);
    const util = num(pos.fund_utilisation_pct), cover = num(pos.owned_fund_cover_pct);
    const coverOk = cover >= 15 || outstanding === 0;

    const headLabels = {
      PROMOTER_SHARE_CAPITAL: ['Promoter / Share Capital', 'Owner ka apna permanent paisa — wapas nahi hota, business ka malikana hissa.'],
      DIRECTOR_LOAN: ['Director / Owner Loan', 'Owner ne company ko udhaar diya — repayable, interest bhi lag sakta hai.'],
      BANK_TERM_LOAN: ['Bank / NBFC Term Loan', 'Onward lending ke liye bank se liya gaya term loan — sabse bada scaling lever.'],
      CASH_CREDIT: ['Cash Credit / Overdraft', 'Portfolio ke against CC/OD limit — jitna utilise karo utna hi interest.'],
      REFINANCE: ['Refinance Line (SIDBI / Mudra)', 'Refinance agency se sasta fund — MFI ke liye lowest cost of funds.'],
    };

    const fundRows = heads.map((h) => {
      const lbl = headLabels[h.code] || [h.ledger, ''];
      return `
        <tr>
          <td><strong>${esc(lbl[0])}</strong><div style="font-size:11px;color:#64748b;">Ledger: ${esc(h.ledger)}</div></td>
          <td><span class="mm-badge ${h.kind === 'EQUITY' ? 'mm-badge-success' : (h.kind === 'OWNER_LOAN' ? 'mm-badge-warning' : 'mm-badge-info')}">${esc(h.kind.replace(/_/g, ' '))}</span></td>
          <td>${esc(lbl[1])}</td>
          <td style="text-align:right;font-weight:800;">${fmt(h.balance)}</td>
          <td style="text-align:right;"><button class="mm-btn mm-btn-default mm-btn-sm" data-fund-head="${esc(h.code)}">+ Add</button></td>
        </tr>`;
    }).join('');

    const bankList = banks.length ? banks.map((b) => `<option value="${esc(b.account_no)}">${esc(b.bank_name)} — ${esc(b.account_no)} (${esc(b.account_name)})</option>`).join('')
      : '<option value="">No bank account — add in Master › Bank Account</option>';

    return `
      <div class="erp-funding">
        <div class="erp-kpi-strip">
          <div class="erp-kpi"><span class="erp-kpi-label">OWNED FUNDS</span><span class="erp-kpi-value">${fmt(owned)}</span></div>
          <div class="erp-kpi teal"><span class="erp-kpi-label">BORROWED / MANAGED FUNDS</span><span class="erp-kpi-value">${fmt(borrowed)}</span></div>
          <div class="erp-kpi slate"><span class="erp-kpi-label">TOTAL FUNDS AVAILABLE</span><span class="erp-kpi-value">${fmt(totalFunds)}</span></div>
          <div class="erp-kpi amber"><span class="erp-kpi-label">CASH + BANK LIQUIDITY</span><span class="erp-kpi-value">${fmt(cash + bank)}</span></div>
          <div class="erp-kpi"><span class="erp-kpi-label">OUTSTANDING PORTFOLIO</span><span class="erp-kpi-value">${fmt(outstanding)}</span></div>
          <div class="erp-kpi red"><span class="erp-kpi-label">LENDING HEAD-ROOM</span><span class="erp-kpi-value">${fmt(canLend)}</span></div>
        </div>

        <div class="erp-funding-grid">
          <div class="erp-card">
            <div class="erp-card-head">
              <span>CAPACITY CHECK — KITNA PAISA LAGA SAKTE HAIN</span>
              <span class="mm-badge ${coverOk ? 'mm-badge-success' : 'mm-badge-danger'}">${coverOk ? 'SAFE' : 'OVER-LEVERAGED'}</span>
            </div>
            <div class="erp-card-body">
              <div class="erp-cap-row"><span>Owned funds ("apna paisa")</span><b>${fmt(owned)}</b></div>
              <div class="erp-cap-row"><span>Borrowed funds ("bahar ka paisa")</span><b>${fmt(borrowed)}</b></div>
              <div class="erp-cap-row"><span>Maximum safe portfolio @ ${esc(pos.owned_fund_min_ratio_pct || '15')}% owned-fund cover</span><b>${fmt(maxPort)}</b></div>
              <div class="erp-cap-row"><span>Approved &amp; outstanding portfolio</span><b>${fmt(outstanding)}</b></div>
              <div class="erp-cap-row total"><span>Fresh lending possible (head-room)</span><b>${fmt(headRoom)}</b></div>
              <div class="erp-cap-row total"><span>Actually disbursable now (liquidity cap)</span><b style="color:#047857;">${fmt(canLend)}</b></div>
              <div class="erp-cap-note">
                Rule: owned funds minimum ${esc(pos.owned_fund_min_ratio_pct || '15')}% of portfolio (max ~${esc(pos.leverage_x || '6.67')}x leverage).
                Owner ka apna paisa poora nahi lagta — ${esc(pos.leverage_x || '6.67')}x tak bahar ka fund (bank / NBFC / refinance) use karke portfolio ban sakta hai.
                Isi liye ek ₹25 lakh owned fund ~${fmt(maxPort)} ka lending book support karta hai.
              </div>
            </div>
          </div>

          <div class="erp-card">
            <div class="erp-card-head"><span>PAISA KAHAN SE AAYEGA — FUNDING MIX</span></div>
            <div class="erp-card-body">
              ${[
                ['Owner equity (share capital)', owned && num(pos.promoter_capital), 'Permanent, non-repayable. Balance sheet strong karta hai.'],
                ['Owner loan (director)', num(pos.owner_loan), 'Repayable. Interest expense banta hai, TDS dhyaan me rakhein.'],
                ['Bank term loan / CC-OD', borrowed, 'Portfolio ke against limit. Sabse common MFI scaling route.'],
                ['Refinance / BC partnership', 0, 'SIDBI / Mudra / RMK ya bank-BC model — sasta fund.'],
              ].map(([t, v, d]) => `
                <div class="erp-mix-row">
                  <div class="erp-mix-bar"><span style="width:${totalFunds > 0 ? Math.min(100, Math.round((num(v) / totalFunds) * 100)) : 0}%"></span></div>
                  <div class="erp-mix-text"><b>${esc(t)}</b><span>${fmt(v)}</span></div>
                  <div class="erp-mix-desc">${esc(d)}</div>
                </div>`).join('')}
              <div class="erp-cap-row"><span>Fund utilisation</span><b>${util}%</b></div>
              <div class="erp-cap-row"><span>Owned-fund cover on portfolio</span><b style="color:${coverOk ? '#047857' : '#dc2626'};">${cover}%</b></div>
            </div>
          </div>
        </div>

        <div class="erp-card">
          <div class="erp-card-head">
            <span>CAPITAL / FUND ADD KAREIN — POST REAL DOUBLE ENTRY</span>
            <span style="font-size:10.5px;color:#64748b;font-weight:600;">Dr Cash/Bank &nbsp;·&nbsp; Cr Fund Ledger</span>
          </div>
          <div class="erp-card-body">
            <div class="erp-fund-form">
              <div class="erp-field">
                <label>FUND HEAD</label>
                <select id="fund-head">
                  ${heads.map((h) => `<option value="${esc(h.code)}">${esc((headLabels[h.code] || [h.ledger])[0])}</option>`).join('')}
                </select>
              </div>
              <div class="erp-field">
                <label>AMOUNT (₹)</label>
                <input type="number" id="fund-amount" placeholder="500000.00" min="1" step="0.01" />
              </div>
              <div class="erp-field">
                <label>RECEIVED IN</label>
                <select id="fund-received"><option value="BANK">BANK ACCOUNT</option><option value="CASH">CASH IN HAND</option></select>
              </div>
              <div class="erp-field">
                <label>BANK ACCOUNT</label>
                <select id="fund-bank">${bankList}</select>
              </div>
              <div class="erp-field">
                <label>DATE</label>
                <input type="date" id="fund-date" value="${esc(uiTodayIso())}" />
              </div>
              <div class="erp-field wide">
                <label>REFERENCE / RESOLUTION / UTR</label>
                <input type="text" id="fund-ref" placeholder="Board resolution no / RTGS UTR / cheque no" />
              </div>
              <div class="erp-field">
                <label>INTEREST % (BORROWING ONLY)</label>
                <input type="number" id="fund-rate" placeholder="0.00" step="0.01" min="0" />
              </div>
              <div class="erp-field">
                <label>REPAYMENT TERMS</label>
                <input type="text" id="fund-terms" placeholder="e.g. 36 months, bullet / monthly" />
              </div>
              <div class="erp-field btn">
                <button class="mm-btn mm-btn-primary" id="btn-post-owner-fund">POST FUND ENTRY</button>
              </div>
            </div>
            <div class="erp-cap-note" style="margin-top:10px;">
              Note: entry direct balance ko chhed kar nahi hoti — ek RECEIPT voucher banta hai:
              <b>Dr ${'Cash/Bank'} → Cr Fund Ledger</b>, jisse Cash Book, Ledger aur Trial Balance apne aap update hote hain.
              CASH me add karte waqt us branch ke vault me cash availability check hoti hai.
            </div>
          </div>
        </div>

        <div class="erp-card">
          <div class="erp-card-head"><span>OWNER FUND &amp; BORROWING LEDGERS</span></div>
          <div class="erp-card-body" style="padding:0;">
            <table class="erp-table">
              <thead><tr><th>FUND SOURCE</th><th>TYPE</th><th>KAISE KAAM KARTA HAI</th><th style="text-align:right;">BALANCE</th><th style="text-align:right;">ACTION</th></tr></thead>
              <tbody>${fundRows || '<tr><td colspan="5" style="text-align:center;padding:18px;">No fund ledger yet — post the first capital entry above.</td></tr>'}</tbody>
            </table>
          </div>
        </div>
      </div>
    `;
  }

  async function postOwnerFund() {
    const val = (id) => (document.getElementById(id) || {}).value || '';
    const payload = {
      fund_head: val('fund-head'),
      amount: val('fund-amount'),
      received_in: val('fund-received'),
      fund_date: val('fund-date'),
      reference: val('fund-ref'),
      bank_account: val('fund-bank'),
      interest_rate_pct: val('fund-rate'),
      repayment_terms: val('fund-terms'),
      branch_name: 'INDORE HEAD OFFICE',
    };
    if (!payload.amount || Number(payload.amount) <= 0) { showToast('Amount daalein (0 se bada).', true); return; }
    try {
      const res = await apiCall('/accounting/owner-funds', { method: 'POST', body: payload });
      showToast('Fund entry posted — voucher ' + ((res.voucher && res.voucher.voucher_no) || ''));
      await loadModuleRoute('/funding');
    } catch (e) {
      showToast(e.message, true);
    }
  }


  // ==========================================================================
  // SETTINGS — Umang-parity Company Profile + SMS / WhatsApp event switches
  // ==========================================================================
  function settingToggleRow(key, label, smap) {
    const raw = String(smap[key] || '').toUpperCase();
    const isOn = ['ENABLED', 'ACTIVE', 'YES', 'TRUE', '1'].includes(raw);
    return `
      <div class="set-flag" data-key="${esc(key)}">
        <span class="set-flag-label">${esc(label)}</span>
        <div class="set-toggle">
          <button type="button" class="set-opt ${!isOn ? 'on' : ''}" data-set-val="DISABLED" title="Disable">○</button>
          <button type="button" class="set-opt ${isOn ? 'on' : ''}" data-set-val="ENABLED" title="Enable">✔</button>
          <button type="button" class="set-opt danger" data-set-val="__clear" title="Clear / not applicable">✖</button>
        </div>
      </div>`;
  }

  function settingField(label, key, smap, opts) {
    const o = opts || {};
    const val = smap[key] !== undefined ? smap[key] : (o.default !== undefined ? o.default : '');
    if (o.type === 'select') {
      return `<div class="erp-field" style="margin-bottom:10px;">
        <label>${esc(label)}${o.required ? ' <span style="color:#dc2626;">*</span>' : ''}</label>
        <select data-set-key="${esc(key)}">
          ${(o.options || []).map((op) => `<option value="${esc(op)}" ${String(val).toUpperCase() === String(op).toUpperCase() ? 'selected' : ''}>${esc(op)}</option>`).join('')}
        </select>
      </div>`;
    }
    if (o.type === 'textarea') {
      return `<div class="erp-field" style="margin-bottom:10px;">
        <label>${esc(label)}</label>
        <textarea rows="${o.rows || 3}" data-set-key="${esc(key)}" style="border:1px solid #cbd5e1;border-radius:6px;padding:7px 9px;font-size:12.5px;">${esc(val)}</textarea>
      </div>`;
    }
    return `<div class="erp-field" style="margin-bottom:10px;">
      <label>${esc(label)}${o.required ? ' <span style="color:#dc2626;">*</span>' : ''}</label>
      <input type="${o.type || 'text'}" data-set-key="${esc(key)}" value="${esc(val)}" placeholder="${esc(o.placeholder || '')}" />
    </div>`;
  }

  function cpeRow(label, value, kind) {
    let v = (value === undefined || value === null || String(value).trim() === '') ? 'NIL' : String(value);
    let cls = '';
    if (kind === 'money' && v !== 'NIL') v = fmtMoney(v);
    if (kind === 'date' && v !== 'NIL' && /^\d{4}-\d{2}-\d{2}$/.test(v)) {
      const d = new Date(v + 'T00:00:00');
      v = `${String(d.getDate()).padStart(2, '0')}-${String(d.getMonth() + 1).padStart(2, '0')}-${d.getFullYear()}`;
    }
    if (kind === 'flag' && v !== 'NIL') v = /ACTIVE|ENABLED|TRUE|YES/i.test(v) ? 'TRUE' : 'FALSE';
    if (v === 'FALSE') cls = ' class="cpe-false"';
    return `<tr><th>${esc(label)}</th><td><span${cls}>${esc(v)}</span></td></tr>`;
  }

  // Print / PDF bar shown at the top of every printable modal (was referenced but never defined,
  // which threw "renderSuperAdminQuickModalPdfBar is not defined" and blanked those modals).
  function renderSuperAdminQuickModalPdfBar(docKey, label) {
    return `
      <div class="doc-pdfbar no-print">
        <span class="doc-pdfbar-key">${esc(String(docKey || 'DOCUMENT'))}</span>
        <span class="doc-pdfbar-label">${esc(label || 'Printable document')}</span>
        <button type="button" class="mm-btn mm-btn-default mm-btn-sm" onclick="window.neevPrintModal()">PRINT / SAVE AS PDF</button>
      </div>
    `;
  }
  if (typeof window !== 'undefined') {
    window.neevPrintModal = () => window.print();
  }

