  async function saveSettingsView() {
    const map = {};
    document.querySelectorAll('[data-set-key]').forEach((el) => {
      map[el.getAttribute('data-set-key')] = el.value;
    });
    document.querySelectorAll('.set-flag').forEach((row) => {
      const key = row.getAttribute('data-key');
      const on = row.querySelector('.set-opt.on');
      if (on) {
        const v = on.getAttribute('data-set-val');
        map[key] = v === '__clear' ? 'DISABLED' : v;
      }
    });
    try {
      await apiCall('/settings/bulk-update', { method: 'POST', body: map });
      showToast(`Saved ${Object.keys(map).length} configuration values.`);
      loadModuleRoute('/setting');
    } catch (e) {
      showToast(e.message, true);
    }
  }


