    document.querySelectorAll('[data-toggle-group]').forEach((el) => {
      el.onclick = () => {
        const gid = el.getAttribute('data-toggle-group');
        const rfAppEl = document.querySelector('.rfApp');
        const rfSideEl = document.querySelector('.rfSide');
        // NEEV 4D: live DOM accordion + auto-open collapsed sidebar + smooth page auto-resize
        if (rfAppEl && rfSideEl && false) {
          const wasCollapsed = !!state.sidebarCollapsed;
          if (wasCollapsed) {
            state.sidebarCollapsed = false;
            rfAppEl.classList.remove('rfSidebarClosed', 'rfSidebarHoverOpen');
            rfSideEl.classList.remove('closed', 'rfHoverOpen');
          }
          const wrap = el.closest('.rfGroup');
          const wasOpen = wrap ? wrap.classList.contains('open') : !!state.openGroups[gid];
          const shouldOpen = wasCollapsed ? true : !wasOpen;
          state.openGroups = shouldOpen ? { [gid]: true } : {};

          rfSideEl.querySelectorAll('.rfGroup').forEach((g) => {
            g.classList.remove('open');
            const btn = g.querySelector('.rfNavItem[data-toggle-group]');
            if (btn) {
              btn.classList.remove('open');
              btn.setAttribute('aria-expanded', 'false');
            }
          });
          if (shouldOpen && wrap) {
            wrap.classList.add('open');
            el.classList.add('open');
            el.setAttribute('aria-expanded', 'true');
            setTimeout(() => {
              const rect = wrap.getBoundingClientRect();
              const sideRect = rfSideEl.getBoundingClientRect();
              if (rect.bottom > sideRect.bottom) {
                rfSideEl.scrollBy({ top: Math.min(rect.height, rect.bottom - sideRect.bottom + 24), behavior: 'smooth' });
              }
            }, 180);
          }
          return;
        }
        const navItem = el.closest('.mm-nav-item');
        const subList = navItem ? navItem.querySelector('.mm-subnav-list') : null;
        const isCurrentlyOpen = navItem ? navItem.classList.contains('open') : !!state.openGroups[gid];
        // Single-Open Accordion Rule with smooth live DOM animation (no full-page re-render flash)
        state.openGroups = isCurrentlyOpen ? {} : { [gid]: true };
        document.querySelectorAll('.mm-nav-item.open').forEach((itemEl) => {
          if (itemEl !== navItem) {
            itemEl.classList.remove('open');
            const sl = itemEl.querySelector('.mm-subnav-list');
            if (sl) sl.classList.remove('open');
          }
        });
        if (navItem && subList) {
          navItem.classList.toggle('open', !isCurrentlyOpen);
          subList.classList.toggle('open', !isCurrentlyOpen);
          return;
        }
        renderApp();
      };
    });

