    kycTick: '<svg class="umg-ti-ico" viewBox="0 0 24 24" fill="none" stroke="#2e9e4a" stroke-width="2.4"><path d="M20 6 9 17l-5-5"/></svg>',
    searchRed: '<svg class="umg-ti-ico" viewBox="0 0 24 24" fill="none" stroke="#e53935" stroke-width="2.2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>',
    eyeGrey: '<svg class="umg-ti-ico" viewBox="0 0 24 24" fill="none" stroke="#546e7a" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>',
    folderOpen: '<svg class="umg-ti-ico" viewBox="0 0 24 24" fill="none" stroke="#5c6bc0" stroke-width="2"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>',
